<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {ElMessage} from 'element-plus';import {useAuthApi,isStaleAuthError,dateTime} from '../api';
const api=useAuthApi();
const props=defineProps<{refreshKey:number}>();const emit=defineEmits(['changed']);const items=ref<any[]>([]);const selected=ref<any>(null);const verification=ref('');const busy=ref(false);const approving=ref(true);
let refreshRequest=0;
async function refresh(){const request=++refreshRequest;try{const result=await api('/clinician/bindings');if(request===refreshRequest)items.value=result.items;}catch(e){if(request===refreshRequest&&!isStaleAuthError(e))ElMessage.error((e as Error).message);}}
function open(row:any,approve=true){selected.value=row;verification.value='';approving.value=approve;}
async function review(){busy.value=true;try{await api(`/clinician/bindings/${selected.value.id}/review`,'POST',{approved:approving.value,verificationMethod:verification.value});selected.value=null;await refresh();emit('changed');ElMessage.success(approving.value?'绑定已批准':'申请已拒绝，旧邀请码已失效');}catch(e){if(!isStaleAuthError(e))ElMessage.error((e as Error).message);}finally{busy.value=false;}}
onMounted(refresh);watch(()=>props.refreshKey,refresh);
</script>
<template><section class="page-heading"><div><span class="eyebrow">CONNECTIONS</span><h1>绑定申请</h1><p>通过已有联系渠道核对患者身份，再开放档案访问。</p></div></section><section class="panel"><el-table :data="items" empty-text="目前没有待确认的绑定申请"><el-table-column label="已有档案" min-width="150"><template #default="{row}"><strong>{{row.name}}</strong><small class="block muted">{{row.birth_date}} · {{row.phone||'未留电话'}}</small></template></el-table-column><el-table-column label="申请人填报信息" min-width="200"><template #default="{row}"><strong>{{row.evidence.name}}</strong><small class="block muted">{{row.evidence.birthDate}} · {{row.evidence.phone}}</small></template></el-table-column><el-table-column label="申请时间" width="150"><template #default="{row}">{{dateTime(row.created_at)}}</template></el-table-column><el-table-column label="操作" width="235"><template #default="{row}"><el-button type="primary" plain @click="open(row)">核对并批准</el-button><el-button text @click="open(row,false)">拒绝</el-button></template></el-table-column></el-table></section><el-dialog :model-value="!!selected" @update:model-value="!$event&&(selected=null)" :title="approving?'确认患者绑定':'拒绝绑定申请'" width="500px"><div class="notice-card"><p>患者自填的姓名、出生日期和电话不等于已完成身份验证。请通过建档时已有的电话或当面核对。</p></div><el-form label-position="top"><el-form-item label="核验方式" for="binding-verification"><el-input id="binding-verification" v-model="verification" type="textarea" :rows="3" placeholder="填写实际核验方式及结果" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="selected=null">取消</el-button><el-button type="primary" :loading="busy" @click="review">{{approving?'确认批准':'确认拒绝'}}</el-button></template></el-dialog></template>
